window.HF_CONTENT = {"notices": {"achv": {"title": "美育成果报送 · 现在要发的这份", "text": "同学们好！\n\n现将本学期由学校遴选、汇总后统一报送的一项美术赛事通知如下。这一项不接收个人单独投稿，请按下面的时间把作品交到{{place}}，由学校统一报送。\n\n一、报什么\n「翰墨青春·传承岭南」广东青少年书画大赛（第十届）（第十届，省级，主办：广东新快报社 · 广东省美术家协会 · 广东省书法家协会）。已纳入广东省 2025—2028 学年面向中小学生的全省性竞赛活动名单，学校认可，公益免费。\n\n二、谁可以报、分哪几类\n面向中小学生，按学段分组；设书法组、美术组、当代艺术组（含 AI 辅助创作）三个类别，每人按当届通知限报类别与件数。请对照自己所在组别报名，不要跨组。\n\n三、两个截止时间，都记好\n学校内部收件：{{inner}}（建议值，以科组最终通知为准），交给{{teacher}}，逾期不再汇总。\n官方截稿：2026-12-31。逾期系统关闭不予受理，不要卡最后一天。\n\n四、交什么（缺项按不完整处理）\n1. 书画原作 1 件，按组别尺寸：国画不超过四尺对开，其他画种不超过四开（约 40×60cm）；书法不超过四尺宣纸；数字美术画布不小于 A4、分辨率不低于 100dpi，并附创意说明与原创责任声明。\n2. 报名表：作品名称、作者姓名、学校、年级班级、指导教师、联系方式。\n3. 作品信息卡（含内容说明），按要求贴于作品背面。\n4. 创作说明 400 字以内，写清「主题简介」和「创作过程介绍」——先一句话说清主题，再写怎么构思、怎么修改、为什么这样定稿。\n\n五、怎么交、交给谁\n不接受个人直接向组委会投稿。作品原件、报名表、信息卡、创作说明一并交到{{place}}，由{{teacher}}汇总、学校遴选后统一报送。电子材料按「班级+姓名+作品名+类别」命名，不要自行改尺寸或压缩格式。\n\n六、评委会看什么\n官方同类赛事实行百分制：主题突出、内容充实、健康向上 30 分；色彩关系明确、画面生动和谐 20 分；构图完整、造型生动 20 分；内容新颖、有创意 20 分；画面干净整洁 10 分。一等奖需 90 分及以上，比例约 5%—10%。请先想清楚主题再动笔，留足时间做完成度打磨。\n\n七、必须遵守的红线\n作品须本人原创，不得代笔、高仿、抄袭，不得重复使用往届参赛作品；不得使用未授权字体、图片、音乐；使用 AI 辅助须在创作说明中标注并保留创作过程文件；不得只交复印件、不交原作；尺寸与年龄组别不符一律取消资格且不返稿。\n\n八、有问题找谁\n报名、组别、尺寸任何一项不清楚，{{contact}}，或课后到{{place}}找我，不要自己猜着填。\n\n{{teacher}}\n{{school}}", "default": true}, "prep": {"title": "个人投稿 / 提前备料（本届不报名）", "text": "同学们好！\n\n先说明一件事：下面这些赛事本届报名已经截止，这次**不需要交作品、也不需要报名**，不要按旧通知去投。\n\n1. 宝安区中小学校美术教育成果比赛（作品征集）（区级，本届截稿 2026-06-15）\n\n它们年年办，下一届通知一般在相近月份发布。现在只做一件事：按评分表攒作品。\n1. 主题：先写一句话说清你想表达什么，紧扣当届主题词，这一项占 30 分。\n2. 构图：画 3 张拇指稿选一张，确定视觉焦点，主体占画面三分之一以上。\n3. 色彩：一个主色 + 一个对比色，至少 3 个明度层次。\n4. 完成度：边缘、细节、无污渍，预留三成时间做修整。\n5. 原创：不临摹范画、不用未授权素材；用 AI 辅助要标注并保留过程文件。\n\n同时把创作说明（400 字内，含主题简介与创作过程）和作品信息卡先填好，和原作一起收进作品袋，交到{{place}}由{{teacher}}统一保管。下一届通知一到，直接从袋里取用，不用临时赶。\n\n规格、原创要求、评分维度任何一项不清楚，{{contact}}。\n\n{{teacher}}\n{{school}}", "default": false}, "teach": {"title": "教师报送通知", "text": "各位老师：\n\n本学期仍可报送的教师类赛事共 2 项，均需在官方平台用学校账号登录上传，请提前准备。\n\n1. 第三届宝安区课程育人能力大赛（含艺术学科命题 / 美术命题）（区级，深圳市宝安区教育科学研究院）\n   截止：2026-12-30；平台：宝安区教育资源公共服务平台 / 区教学资源平台（需学校账号登录上传）\n2. 宝安区「雏鹰计划」新教师评比（区级，深圳市宝安区教育科学研究院）\n   截止：2026-12-30；平台：区教学资源平台（需学校账号登录）\n\n材料要点：教学设计 / 命题须附「命题意图 + 素养对应 + 评分标准」三件套；论文须未公开发表、摘要 300 字左右、正文不超过 5000 字、查重不超过 15%，使用 AI 辅助须标注；微课 / 精品课须交视频、教学设计、学习任务单、课件与作业练习。所有材料须真实，禁止虚构、杜撰、抄袭；提交后截图留存回执，逾期系统关闭不予受理。\n\n报名表模板、盖章与平台路径请到{{place}}找{{teacher}}，有疑问{{contact}}。\n\n{{teacher}}\n{{school}}", "default": false}, "all": {"title": "全文（三类合并）", "text": "同学们、各位老师：\n\n现将本学期美术类赛事分两类说明，请注意**只有第一类现在要交作品**。\n\n【一、现在可以报，需要交作品】\n「翰墨青春·传承岭南」广东青少年书画大赛（第十届）（省级，广东新快报社 · 广东省美术家协会 · 广东省书法家协会），官方截稿 2026-12-31，学校内部收件 {{inner}}。\n设书法组、美术组、当代艺术组；不接收个人单独投稿，作品交{{place}}由{{teacher}}汇总后统一报送。\n须交：原作（国画≤四尺对开、其他画种≤四开约 40×60cm、数字美术≥A4 且≥100dpi）、报名表、作品信息卡、400 字内创作说明（主题简介 + 创作过程）。\n评分：主题 30 / 色彩 20 / 构图 20 / 创意 20 / 整洁 10，一等奖需 90 分以上。\n红线：须本人原创，禁代笔、高仿、抄袭、重复往届作品；AI 辅助须标注；禁未授权素材；须交原作；规格与组别不符取消资格。\n\n【二、本届已截止，本次不报名，只提前备料】\n1. 宝安区中小学生禁毒绘画创作比赛（区级，本届截稿 2026-06-20）\n2. 第三十届全国中小学生绘画书法作品比赛（国级，本届截稿 2026-06-30）\n3. 深圳市学生网络夏令营宝安区选拔赛（电脑绘画）（区级，本届截稿 2026-07-10）\n这些赛事年年办，现在按上面的评分维度攒作品、写好创作说明与信息卡即可，下一届通知一到直接投。\n\n【三、教师报送（老师自行准备）】\n1. 第三届宝安区课程育人能力大赛（含艺术学科命题 / 美术命题），截止 2026-12-30，平台：宝安区教育资源公共服务平台 / 区教学资源平台（需学校账号登录上传）\n2. 宝安区「雏鹰计划」新教师评比，截止 2026-12-30，平台：区教学资源平台（需学校账号登录）\n\n任何一项不清楚，{{contact}}，或到{{place}}找{{teacher}}，不要自己猜着填。\n\n{{teacher}}\n{{school}}", "default": false}}, "tpl": {"creation": {"title": "创作说明（400 字内）", "hint": "主题简介 + 创作过程介绍，多赛硬性要求", "text": "作品名称：\n作者 / 年级班级：\n指导教师：\n类别 / 组别：\n\n一、主题简介（约 120 字）\n我想表达的是：________。\n选择这个角度是因为：________。\n画面里 ____、____、____ 三处都是为这个主题服务的，与当届主题「____」的对应关系是：________。\n\n二、创作过程介绍（约 250 字）\n构思：先写了 ____ 个方案，最后选第 ____ 个，原因是 ________。\n草图：画了 3 张构图小稿，确定了以 ____ 为视觉焦点，主体占画面约 ____。\n色彩 / 笔墨：主色 ____，对比色 ____，明度层次 ____ 层，调整了 ____ 次。\n修改：把 ____ 改成 ____，因为 ________；保留 ____ 是为了 ________。\n定稿：完成度检查了边缘、细节、污渍与尺寸，最终规格 ____ cm。\n\n三、原创与辅助声明\n本作品由本人独立完成，未使用代笔、高仿或他人作品；使用素材：____（已获授权 / 自摄 / 自绘）；\nAI 辅助：□ 无　□ 有，具体环节与工具：________（按当届要求标注）。"}, "card": {"title": "作品信息卡（贴作品背面）", "hint": "缺项按不完整处理", "text": "作品名称：\n作者姓名：\n所在区 / 县（市、区）：\n学校名称：\n年级 / 班级：\n指导教师：\n作品类别 / 组别：\n作品尺寸：\n创作说明（内容说明）：\n联系电话：\n原创承诺：本人承诺作品为原创，无代笔、抄袭、重复往届参赛情形。\n作者 / 监护人签字：　　　　　日期："}, "thesis": {"title": "教学研究论文提纲", "hint": "摘要 300 字、正文≤5000 字、未公开发表、查重≤15%", "text": "题目（点明论题主旨，不空泛）：\n\n摘要（约 300 字）：背景与问题 / 做法 / 成效 / 结论，四句写完。\n关键词（3—5 个）：\n\n一、背景与问题（约 600 字）\n本校 / 本区美育教学中的真实痛点，附可核查的数据或课堂记录。\n\n二、做法（约 1800 字）\n2.1 设计与依据（对标课标与核心素养）\n2.2 实施过程（时间、对象、课例、活动）\n2.3 关键策略（写清「怎么做」，可被别人复用）\n\n三、成效（约 1200 字）\n学生作品 / 测评 / 问卷的前后对比，给数据，不写形容词。\n\n四、探讨（约 800 字）\n局限、可推广条件、下一步。\n\n参考文献（近 3 年占比不低于 40%，格式规范）。\n声明：未公开发表；查重率 ____%；AI 辅助环节：____（按当届要求标注）。"}, "design": {"title": "教学设计 / 命题三件套", "hint": "缺一项基本无缘一等奖", "text": "【一、命题意图】\n对应课标条目：\n要考查的核心素养：\n为什么这样设问（不要写「巩固知识」）：\n预期学生表现：\n\n【二、素养对应表】\n| 题目 / 任务 | 对应素养维度 | 考查层级 | 分值 |\n|---|---|---|---|\n|  |  |  |  |\n\n【三、评分标准】\n分档（优秀 / 良好 / 合格 / 待改进）与各档可观察表现：\n典型答案 / 作品样例：\n常见错误与扣分点：\n\n附：教学设计（规范教案格式：目标、学情、重难点、过程、评价、板书 / 演示、反思）。\n附：课堂实录视频须在真实课堂环境录制（一节课）。"}, "micro": {"title": "精品课 / 微课材料清单", "hint": "按平台节点录制，五件齐", "text": "□ 微课视频（5—10 分钟；按国家中小学智慧教育平台目录节点录制）\n□ 教学设计（对照国家课程标准，体现学科德育与综合育人）\n□ 学习任务单\n□ 课件（PPT，16:9）\n□ 作业练习（学科课程类须提交）\n□ 平台上传回执截图（jpk.basic.smartedu.cn，逐级遴选）\n备注：同一目录节点各省只推 1 节，先在校内、区内占位；比拼课堂实效与制作规范，不是花哨。"}, "fill": {"title": "投稿填报内容", "hint": "一次填好，粘进官方表单即可", "text": "赛事名称：{{tname}}\n参赛类别 / 组别：{{grade}}\n作品名称：\n作者姓名：\n学校名称：{{school}}\n年级 / 班级：\n指导教师：{{teacher}}\n联系电话：{{contact}}\n作品尺寸 / 规格：\n使用软件（数字美术填写）：\n创作说明（400 字内，另附）：\n原创承诺：已阅并同意，作品为本人原创，无代笔、抄袭、重复往届参赛情形。\nAI 辅助声明：□ 无　□ 有（环节与工具：______）\n报送方式：学校遴选后统一报送（不接收个人单独投稿）\n官方截止：{{deadline}}　学校内部收件：{{inner}}"}}, "targets": [{"id": "ba-course-3", "name": "第三届宝安区课程育人能力大赛（含艺术学科命题 / 美术命题）", "tier": "区", "deadline": "2026-12-30", "org": "深圳市宝安区教育科学研究院", "way": "teach", "portal": "宝安区教育资源公共服务平台 / 区教学资源平台（需学校账号登录上传）", "url": "https://www.baoan.gov.cn/", "materials": ["参赛报名表（区教科院统一模板，需学校盖章）", "教学设计 / 命题双向细目表（艺术学科按美术课标命题）", "现场说课或命题阐释 PPT（16:9，≤20 页）", "近一学年该班学生作业样本 3-5 份（佐证学习效果）", "校本教研证明（科组磨课记录、听课评价表）"], "left": 55}, {"id": "ba-chuying", "name": "宝安区「雏鹰计划」新教师评比", "tier": "区", "deadline": "2026-12-30", "org": "深圳市宝安区教育科学研究院", "way": "teach", "portal": "区教学资源平台（需学校账号登录）", "url": "https://www.baoan.gov.cn/", "materials": ["新教师成长档案（师徒结对记录、听课笔记）", "一节完整课的教学设计与反思", "粉笔字 / 专业技能展示材料（美术可交作品集）", "指导教师推荐意见（需签字）"], "left": 55}, {"id": "gd-hanmo-youth", "name": "「翰墨青春·传承岭南」广东青少年书画大赛（第十届）", "tier": "省", "deadline": "2026-12-31", "org": "广东新快报社 · 广东省美术家协会 · 广东省书法家协会", "way": "achv", "portal": "大赛官方征稿通道 / 学校集体报名", "url": "http://news.xkb.com.cn/articleDetail/502682", "materials": ["学生书画原作（按组别尺寸）", "报名表（学生+指导教师+学校）", "原创承诺（严查代笔/高仿）"], "left": 56}], "defaultTarget": "gd-hanmo-youth", "cfgDefault": {"school": "本校", "teacher": "美术组老师", "place": "美术办公室", "inner": "2026-12-20", "contact": "班级群私信我", "grade": "按组别"}, "materials": ["学生书画原作（按组别尺寸）", "报名表（学生+指导教师+学校）", "原创承诺（严查代笔/高仿）"], "spec": ["文件命名与作品编号一致（班级+姓名+作品名+类别），错一位就可能对不上号", "尺寸、分辨率、时长、体积按当届通知导出，不自行「优化」", "类别与报送通道对应，投错通道等于未投", "作者信息、创作说明、原创声明字段全部填齐，缺项按不完整处理", "保留源文件 / 分层文件，评委要补充或微调时拿得出", "字体、图片、音乐均获授权或自绘自摄", "截止时间以服务器为准，提前提交并截图留存回执", "原件按要求寄送 / 交送，不只交复印图片"], "scoreCheck": ["先写一句话说清主题，写不出就别动笔（对应 30 分档）", "当届主题词在创作说明里明确出现，避免跑题直接出局", "画 3 张构图小稿选一张，确定视觉焦点（20 分档）", "限色：主色 + 对比色 + 中性色，至少 3 个明度层次（20 分档）", "一个反常识的切入点，不临摹范画（20 分档）", "留 30% 时间修边缘、细节、污渍、折角（10 分档）", "原创自查：不代笔、不重复往届、AI 辅助按当届要求标注（资格项）", "组织 20 名以上学生批量打磨，同时冲学生奖与指导教师奖"], "open": [{"name": "第三届宝安区课程育人能力大赛（含艺术学科命题 / 美术命题）", "deadline": "2026-12-30", "left": 55}, {"name": "宝安区「雏鹰计划」新教师评比", "deadline": "2026-12-30", "left": 55}, {"name": "「翰墨青春·传承岭南」广东青少年书画大赛（第十届）", "deadline": "2026-12-31", "left": 56}], "past": [{"name": "深圳市学科美育微课大赛（宝安选拔）", "deadline": "2026-05-15"}, {"name": "宝安区中小学校美术教育成果比赛（作品征集）", "deadline": "2026-06-15"}, {"name": "宝安区中小学生禁毒绘画创作比赛", "deadline": "2026-06-20"}, {"name": "第三十届全国中小学生绘画书法作品比赛", "deadline": "2026-06-30"}, {"name": "深圳市学生网络夏令营宝安区选拔赛（电脑绘画）", "deadline": "2026-07-10"}, {"name": "“基础教育精品课”遴选（教育部办公厅）", "deadline": "2026-10-20"}], "today": "2026-11-05"};
